#include <stdio.h>
#include <string.h>

#define MAX 100

typedef struct {
    char name[32];
    char phone[20];
} Contact;

int add_one(Contact book[], int n, char *name, char *phone) {
    if (n >= MAX) {
        printf("记满了喵\n");
        return n;
    }
    strcpy(book[n].name, name);
    strcpy(book[n].phone, phone);
    return n + 1;
}

void list_all(Contact book[], int n) {
    if (n == 0) {
        printf("还一条都没有喵\n");
        return;
    }
    for (int i = 0; i < n; i++) {
        printf("%d. %s %s\n", i + 1, book[i].name, book[i].phone);
    }
}

int save_all(Contact book[], int n, char *path) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        printf("打不开喵\n");
        return 0;
    }
    for (int i = 0; i < n; i++) {
        fprintf(fp, "%s %s\n", book[i].name, book[i].phone);
    }
    fclose(fp);
    printf("存好了喵\n");
    return 1;
}

int load_all(Contact book[], char *path) {
    FILE *fp = fopen(path, "r");
    int n = 0;
    if (fp == NULL) {
        printf("还没有册子，这次从空的开始喵\n");
        return 0;
    }
    while (n < MAX && fscanf(fp, "%31s %19s", book[n].name, book[n].phone) == 2) {
        n = n + 1;
    }
    fclose(fp);
    return n;
}

int main(void) {
    Contact book[MAX];
    int n = load_all(book, "book.txt");
    int running = 1;

    while (running) {
        printf("=== 小鱼干通讯录 ===\n");
        printf("1 添加  2 列出  0 退出\n");
        printf("请选择> ");

        int choice;
        if (scanf("%d", &choice) != 1) {
            running = 0;
            break;
        }

        if (choice == 1) {
            char name[32];
            char phone[20];
            printf("名字> ");
            scanf("%31s", name);
            printf("号码> ");
            scanf("%19s", phone);
            n = add_one(book, n, name, phone);
        } else if (choice == 2) {
            list_all(book, n);
        } else {
            running = 0;
        }
    }

    save_all(book, n, "book.txt");
    printf("\n再见喵\n");
    return 0;
}

explanationTemplate:
**这一道是整课的合影**喵：图纸、条数、加一条、列出来、存、读，再加上前面学过的「反复问」和「先检查、再干活」。

**① 为什么一进门先读一趟册子？** 因为小册子得**接着上一回**用。读不回来（第一次跑，册子文件还不存在）不算出事 —— 印一句 `还没有册子，这次从空的开始喵`，条数算 0 就行。**这就是「先检查、再干活」**：先看看盘上有没有东西，再决定从哪儿起步。

**② 那个反复问的圈什么时候停？**

```c
int running = 1;
while (running) {
```

它不管本喵说了什么，只管那个开关 `running`。下面三条路各管一件事：说 `1` 就接着问名字和号码、说 `2` 就列出来、**说别的就把开关关掉**。

**③ 说不明白的时候也算「别的」。**

```c
if (scanf("%d", &choice) != 1) {
    running = 0;
    break;
}
```

`scanf` 交回来的数就是「这一趟读成了几样」，读成一个整数才算 1。**读不到就交别的数** —— 这时候要是还往下走，那个 `choice` 里躺着的是个来路不明的值，本喵就照着它去挑路了。所以先检查、**然后把开关关掉**。

**④ 提示为什么不带换行？** 因为 `printf("请选择> ")` 是**印完就停在那里**，光标不往下跳 —— 本喵接着说的东西就会跟在同一行后面。看样例输出就能看明白：`请选择> ` 后面直接跟上了 `名字> `，再跟上 `号码> `，三条挤成一行。这不是印坏了，是**故意不换行**。**要是想让它好看点，自己加一句换行就行**；这道题照着课文的样子来。

**⑤ 收工时那一次存。** 反复问结束时，册子只在**内存**里；不存到盘上，下一次跑就白忙了。所以关掉那个反复问的开关以后立刻 `save_all` —— 这才是「小册子真能留得住」的那一步。

**⑥ 开头那个空行别丢。** 最后印的是 `\n再见喵\n` —— **前头那个换行是给 `请选择> ` 收尾的**，不然「再见喵」会跟在那句提示后面挤成一团。
